REQUIRED_OUTPUTS = (
    "MTPro2UnicodeMath-Regular.otf",
    "MTPro2UnicodeMath-Script.otf",
    "MTPro2UnicodeMath-ScriptScript.otf",
    "mtpro2-unicode-compat.sty",
    "mtpro2-unicode-mathkern.sty",
    "mtpro2-unicode-operators.sty",
    "mtpro2-unicode-geometry.sty",
    "effective-final-mapping-augmented.json",
    "tfm-metrics.json",
)
REQUIRED_AUDITS = (
    "mtpro2-pipeline-outline-audit.json",
    "mtpro2-pipeline-math-table-audit.json",
    "mtpro2-pipeline-math-provenance.json",
)
FONT_EXTENSIONS = {".pfb", ".pfm", ".tfm", ".otf", ".ttf", ".afm", ".vf", ".enc"}


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def json_dump(path: Path, data: dict[str, Any]) -> None:
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def extract_toolchain(destination: Path) -> None:
    payload = base64.b85decode(PAYLOAD_B85.encode("ascii"))
    with zipfile.ZipFile(__import__("io").BytesIO(payload)) as archive:
        bad = [name for name in archive.namelist() if Path(name).suffix.lower() in FONT_EXTENSIONS]
        if bad:
            raise RuntimeError("embedded package unexpectedly contains font assets: " + ", ".join(bad))
        archive.extractall(destination)


def default_fontforge() -> str:
    candidates = [
        Path("D:/FontForge/bin/ffpython.exe"),
        Path("D:/FontForgeBuilds/bin/ffpython.exe"),
        Path("C:/Program Files (x86)/FontForgeBuilds/bin/ffpython.exe"),
        Path("C:/Program Files/FontForgeBuilds/bin/ffpython.exe"),
    ]
    for candidate in candidates:
        if candidate.is_file():
            return str(candidate)
    return ""


def source_errors(source: Path) -> list[str]:
    errors: list[str] = []
    if not source.is_dir():
        return [f"MTPro2 source directory does not exist: {source}"]
    if not (source / "mtpro2_full.tex").is_file():
        errors.append("missing mtpro2_full.tex")
    if not any(source.glob("*.pfb")):
        errors.append("no .pfb outline files found")
    if not any(source.glob("*.tfm")):
        errors.append("no .tfm metric files found")
    return errors


def preflight(source: Path, output: Path, fontforge_python: Path, resume: bool) -> list[str]:
    errors = source_errors(source)
    if output.name.lower() == "build":
        errors.append("output directory must not be named build")
    if source.resolve() == output.resolve():
        errors.append("source and output directories must be different")
    if output.exists() and any(output.iterdir()) and not resume:
        errors.append("output directory is nonempty; choose an empty directory or pass --resume")
    if not fontforge_python.is_file():
        errors.append(f"FontForge Python executable does not exist: {fontforge_python}")
    return errors


def verify_output(output: Path) -> dict[str, Any]:
    errors: list[str] = []
    checks: dict[str, Any] = {}
    manifest_path = output / "tests" / "mtpro2-pipeline-manifest.json"
    manifest: dict[str, Any] = {}
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        checks["manifest"] = "present"
    except Exception as exc:
        errors.append(f"cannot read pipeline manifest: {exc}")

    for name in REQUIRED_OUTPUTS:
        path = output / name
        checks[f"output:{name}"] = path.is_file()
        if not path.is_file():
            errors.append(f"missing generated output: {name}")

    for name, record in manifest.get("outputs", {}).items():
        path = Path(str(record.get("path", "")))
        expected = record.get("sha256")
        if not path.is_file():
            errors.append(f"manifest output missing: {name}: {path}")
        elif expected and sha256(path) != expected:
            errors.append(f"manifest output hash mismatch: {name}: {path}")

    for name in REQUIRED_AUDITS:
        path = output / "tests" / name
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            passed = data.get("passed") is True and not data.get("errors") and not data.get("failures")
            checks[f"audit:{name}"] = passed
            if not passed:
                errors.append(f"audit did not pass: {name}")
        except Exception as exc:
            errors.append(f"cannot read audit {name}: {exc}")

    commands = manifest.get("commands", [])
    checks["pipeline_command_count"] = len(commands)
    failed_commands = [entry.get("command") for entry in commands if entry.get("returncode") != 0]
    if failed_commands:
        errors.append(f"pipeline manifest contains failed command(s): {failed_commands}")

    try:
        from fontTools.ttLib import TTFont
    except Exception as exc:
        errors.append(f"FontTools is required for OTF verification: {exc}")
    else:
        for name in REQUIRED_OUTPUTS[:3]:
            path = output / name
            if not path.is_file():
                continue
            try:
                font = TTFont(path, lazy=True)
                tables = set(font.keys())
                checks[f"math-table:{name}"] = "MATH" in tables
                if "MATH" not in tables:
                    errors.append(f"generated font lacks OpenType MATH table: {name}")
                font.close()
            except Exception as exc:
                errors.append(f"cannot parse generated font {name}: {exc}")

    return {
        "status": "PASS" if not errors else "FAIL",
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "output_dir": str(output),
        "checks": checks,
        "errors": errors,
        "scope": "Pipeline manifest, hashes, in-pipeline audits, and OpenType-MATH parseability. "
                 "Visual equivalence requires the optional legacy-vs-Unicode regression fixture set.",
    }


def run_conversion(source: Path, output: Path, fontforge_python: Path, resume: bool, install_to: Path | None) -> int:
    errors = preflight(source, output, fontforge_python, resume)
    if errors:
        print("Preflight failed:", file=sys.stderr)
        print("\n".join(f"  - {item}" for item in errors), file=sys.stderr)
        return 2
    output.mkdir(parents=True, exist_ok=True)
    log_path = output / "mtpro2-converter-run.log"
    with tempfile.TemporaryDirectory(prefix="mtpro2-unicode-toolchain-") as temp_name:
        toolchain = Path(temp_name) / "toolchain"
        extract_toolchain(toolchain)
        command = [
            sys.executable, str(toolchain / "rebuild_unicode_math.py"),
            "--source-dir", str(source), "--work-dir", str(output),
            "--tests-dir", str(output / "tests"), "--fontforge-python", str(fontforge_python),
        ]
        # Windows ffpython.exe loads DLLs from FontForge's bin directory.  A
        # portable launcher is commonly started from elsewhere, so preserve
        # the caller environment and explicitly make that directory visible
        # to every descendant pipeline command.
        environment = os.environ.copy()
        environment["PATH"] = str(fontforge_python.parent) + os.pathsep + environment.get("PATH", "")
        completed = subprocess.run(
            command,
            text=True,
            encoding="utf-8",
            errors="replace",
            capture_output=True,
            env=environment,
        )
        log_path.write_text(completed.stdout + "\n--- STDERR ---\n" + completed.stderr, encoding="utf-8")
        if completed.returncode:
            print(completed.stdout)
            print(completed.stderr, file=sys.stderr)
            print(f"Conversion failed; diagnostic log: {log_path}", file=sys.stderr)
            return completed.returncode
    report = verify_output(output)
    report_path = output / "mtpro2-converter-verification.json"
    json_dump(report_path, report)
    print(json.dumps(report, ensure_ascii=False, indent=2))
    if report["status"] != "PASS":
        print(f"Verification failed; report: {report_path}", file=sys.stderr)
        return 3
    if install_to:
        install_to.mkdir(parents=True, exist_ok=True)
        for name in REQUIRED_OUTPUTS[:7]:
            shutil.copy2(output / name, install_to / name)
        print(f"Installed runtime files to: {install_to}")
    print(f"Conversion and verification passed. Output: {output}")
    return 0


def self_check() -> int:
    try:
        with tempfile.TemporaryDirectory(prefix="mtpro2-unicode-selfcheck-") as temp_name:
            root = Path(temp_name)
            extract_toolchain(root)
            required = {"rebuild_unicode_math.py", "fontforge_build.py", "continuation_gate.py"}
            missing = [name for name in required if not (root / name).is_file()]
            if missing:
                raise RuntimeError("bundle is incomplete: " + ", ".join(missing))
            if any(path.suffix.lower() in FONT_EXTENSIONS for path in root.rglob("*")):
                raise RuntimeError("bundle contains prohibited font source or output files")
    except Exception as exc:
        print(f"Self-check failed: {exc}", file=sys.stderr)
        return 1
    print("Self-check passed: embedded toolchain is complete and contains no MTPro2 font assets.")
    return 0


def start_gui() -> int:
    try:
        import tkinter as tk
        from tkinter import filedialog, messagebox, scrolledtext
    except Exception as exc:
        print(f"GUI unavailable ({exc}); use --help for command-line usage.", file=sys.stderr)
        return 2

    root = tk.Tk()
    root.title(APP_NAME)
    root.minsize(760, 480)
    fields: dict[str, tk.StringVar] = {
        "source": tk.StringVar(),
        "output": tk.StringVar(value=str(Path.cwd() / "MTPro2Unicode-output")),
        "fontforge": tk.StringVar(value=default_fontforge()),
        "install": tk.StringVar(),
    }
    intro = ("This program does not include MTPro2. Select your own licensed MTPro2 folder "
             "(must contain mtpro2_full.tex, .pfb and .tfm files), then choose an empty output folder.\n"
             "Outputs: three Unicode-MATH OTF files, four Cloverbook compatibility .sty files, "
             "mapping/metric data, a command manifest, and a PASS/FAIL verification report.")
    tk.Label(root, text=intro, justify="left", wraplength=720).pack(padx=16, pady=(16, 8), anchor="w")
    form = tk.Frame(root)
    form.pack(fill="x", padx=16)
    labels = [("MTPro2 source directory", "source", "dir"), ("Output directory", "output", "dir"),
              ("FontForge ffpython.exe", "fontforge", "file"), ("Optional install directory", "install", "dir")]
    for row, (label, key, kind) in enumerate(labels):
        tk.Label(form, text=label, width=24, anchor="w").grid(row=row, column=0, sticky="w", pady=3)
        tk.Entry(form, textvariable=fields[key], width=72).grid(row=row, column=1, sticky="ew", pady=3)
        def choose(k: str = key, mode: str = kind) -> None:
            value = filedialog.askdirectory() if mode == "dir" else filedialog.askopenfilename(filetypes=[("Executable", "*.exe"), ("All files", "*.*")])
            if value:
                fields[k].set(value)
        tk.Button(form, text="Browse", command=choose).grid(row=row, column=2, padx=(6, 0))
    form.grid_columnconfigure(1, weight=1)
    log = scrolledtext.ScrolledText(root, height=14, state="disabled")
    log.pack(fill="both", expand=True, padx=16, pady=8)
    buttons = tk.Frame(root)
    buttons.pack(fill="x", padx=16, pady=(0, 16))
    def write(message: str) -> None:
        log.configure(state="normal")
        log.insert("end", message + "\n")
        log.see("end")
        log.configure(state="disabled")
    def launch(dry_run: bool) -> None:
        args = [sys.executable, str(Path(__file__).resolve()), "--no-gui", "--source-dir", fields["source"].get(),
                "--output-dir", fields["output"].get(), "--fontforge-python", fields["fontforge"].get()]
        if fields["install"].get().strip():
            args += ["--install-to", fields["install"].get()]
        if dry_run:
            args.append("--dry-run")
        def worker() -> None:
            completed = subprocess.run(args, text=True, encoding="utf-8", errors="replace", capture_output=True)
            root.after(0, lambda: write(completed.stdout + completed.stderr))
            if completed.returncode:
                root.after(0, lambda: messagebox.showerror(APP_NAME, "Failed. Read the diagnostic text below."))
            else:
                root.after(0, lambda: messagebox.showinfo(APP_NAME, "Passed. See the verification report in the output directory."))
        threading.Thread(target=worker, daemon=True).start()
    tk.Button(buttons, text="Check inputs", command=lambda: launch(True)).pack(side="left")
    tk.Button(buttons, text="Convert and verify", command=lambda: launch(False)).pack(side="left", padx=8)
    tk.Button(buttons, text="Close", command=root.destroy).pack(side="right")
    root.mainloop()
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=APP_NAME)
    parser.add_argument("--gui", action="store_true", help="open the guided graphical interface")
    parser.add_argument("--no-gui", action="store_true", help="run from the command line")
    parser.add_argument("--source-dir", type=Path, help="licensed MTPro2 installation directory")
    parser.add_argument("--output-dir", type=Path, help="empty directory for generated files; never named build")
    parser.add_argument("--fontforge-python", type=Path, help="FontForge ffpython.exe")
    parser.add_argument("--install-to", type=Path, help="optional runtime install destination")
    parser.add_argument("--resume", action="store_true", help="allow a nonempty output directory")
    parser.add_argument("--dry-run", action="store_true", help="validate inputs and show planned outputs without conversion")
    parser.add_argument("--verify-only", type=Path, metavar="OUTPUT_DIR", help="verify an existing conversion output")
    parser.add_argument("--self-check", action="store_true", help="validate this single-file package without MTPro2")
    args = parser.parse_args()
    if args.self_check:
        return self_check()
    if args.verify_only:
        report = verify_output(args.verify_only.resolve())
        print(json.dumps(report, ensure_ascii=False, indent=2))
        return 0 if report["status"] == "PASS" else 3
    if args.gui or (not args.no_gui and not any((args.source_dir, args.output_dir, args.fontforge_python))):
        return start_gui()
    if not (args.source_dir and args.output_dir and args.fontforge_python):
        parser.error("--source-dir, --output-dir, and --fontforge-python are required in command-line mode")
    source, output, fontforge = args.source_dir.resolve(), args.output_dir.resolve(), args.fontforge_python.resolve()
    errors = preflight(source, output, fontforge, args.resume)
    if args.dry_run:
        if errors:
            print("Preflight failed:\n" + "\n".join(f"  - {item}" for item in errors), file=sys.stderr)
            return 2
        print("Preflight passed. The conversion will generate:")
        for name in REQUIRED_OUTPUTS:
            print(f"  - {output / name}")
        print(f"  - {output / 'tests' / 'mtpro2-pipeline-manifest.json'}")
        print(f"  - {output / 'mtpro2-converter-verification.json'}")
        return 0
    return run_conversion(source, output, fontforge, args.resume, args.install_to)


if __name__ == "__main__":
    raise SystemExit(main())
